<?php session_start();include 'koneksi.php';$error='';if(isset($_POST['login'])){$u=trim($_POST['username']);$p=md5($_POST['password']);$s=mysqli_prepare($conn,'SELECT * FROM users WHERE username=? AND password=?');mysqli_stmt_bind_param($s,'ss',$u,$p);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);if($d=mysqli_fetch_assoc($r)){$_SESSION['login']=true;$_SESSION['id']=$d['id'];$_SESSION['nama']=$d['nama'];$_SESSION['role']=$d['role'];header('Location: dashboard.php');exit;}else{$error='Username atau password salah!';}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Login Rental Mobil</title><link rel="stylesheet" href="assets/style.css"></head><body class="login-body"><div class="login-box"><h2>🚗 Rental Mobil</h2><?php if($error):?><div class="error"><?=$error?></div><?php endif;?><form method="post"><label>Username</label><input name="username" required><label>Password</label><input type="password" name="password" required><button name="login">Login</button></form><p class="small">admin / admin123<br>petugas / petugas123</p></div></body></html>
